import { tv, type VariantProps } from "@/lib/beton/tv";

export const logoCloud = tv({
  slots: {
    list: "flex flex-wrap items-center justify-center gap-4",
    item: [
      "flex min-h-16 items-center justify-center border-3 border-border bg-raised px-6",
      "font-display font-black tracking-tight uppercase text-foreground",
    ],
  },
  variants: {
    size: {
      sm: { item: "min-h-12 px-4 text-sm" },
      md: { item: "min-h-16 px-6 text-lg" },
      lg: { item: "min-h-20 px-8 text-2xl" },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type LogoCloudVariants = VariantProps<typeof logoCloud>;

import { logoCloud, type LogoCloudVariants } from "@/lib/beton/recipes/logo-cloud.recipe";
import type { ReactNode } from "react";
import { Section, type SectionProps } from "@/components/ui/beton/section";

export interface LogoCloudProps extends Omit<SectionProps, "children">, LogoCloudVariants {
  /** The names, as words or as marks. */
  logos: ReactNode[];
  /** Classes for the row itself. */
  listClassName?: string;
}

/** A row of the names that use the thing. */
export function LogoCloud({ logos, size = "md", listClassName, ...props }: LogoCloudProps) {
  const styles = logoCloud({ size });
  return (
    <Section align="center" {...props}>
      <ul className={styles.list({ class: listClassName })}>
        {logos.map((logo, index) => (
          <li key={index} className={styles.item()}>
            {logo}
          </li>
        ))}
      </ul>
    </Section>
  );
}
